+  <script>
+    (() => {
+      "use strict";
+      const data = window.REPORT_DATA || {};
+      const meta = data.meta || {};
+      const summary = data.summary || {};
+      const previous = data.summary_previous || {};
+      const rates = data.rates || {};
+      const deltas = data.deltas || {};
+      const byPlatform = data.by_platform || {};
+      const series = Array.isArray(data.daily_series) ? data.daily_series : [];
+      const rows = data.rows || {};
+      const breakdowns = data.breakdowns || {};
+      const narratives = Array.isArray(data.narratives) ? data.narratives : [];
+      const labels = {
+        spend: "Inversión", impressions: "Impresiones", reach: "Alcance", clicks: "Clics",
+        conversions: "Conversiones", results: "Resultados", lead: "Clientes potenciales",
+        engagement: "Interacciones", post_engagement: "Interacciones con publicaciones",
+        followers: "Seguidores", views: "Visualizaciones", video_views: "Vistas de video",
+        likes: "Me gusta", comments: "Comentarios", shares: "Veces compartido",
+        ctr: "CTR", cpc: "CPC", cpm: "CPM", cpa: "CPA", conversion_rate: "Tasa de conversión"
+      };
+      const moneyMetrics = new Set(["spend", "cpc", "cpm", "cpa", "cost", "cost_per_result"]);
+      const percentMetrics = new Set(["ctr", "conversion_rate", "share"]);
+      const metricPriority = ["spend", "impressions", "reach", "engagement", "followers", "views", "video_views", "clicks", "conversions", "likes", "comments", "shares"];
+      const number = value => typeof value === "number" && Number.isFinite(value);
+      const element = (tag, className, value) => {
+        const node = document.createElement(tag);
+        if (className) node.className = className;
+        if (value !== undefined && value !== null) node.textContent = String(value);
+        return node;
+      };
+      const show = (node, visible) => { node.hidden = !visible; return visible; };
+      const metricLabel = key => labels[key] || key.replaceAll("_", " ").replace(/\b\w/g, letter => letter.toUpperCase());
+      const platformLabel = key => key.replaceAll("_", " ").replace(/\b\w/g, letter => letter.toUpperCase());
+      const format = (key, value) => {
+        if (!number(value)) return "";
+        if (moneyMetrics.has(key)) return new Intl.NumberFormat("es-EC", { style: "currency", currency: "USD", maximumFractionDigits: 2 }).format(value);
+        if (percentMetrics.has(key) || key.startsWith("delta_")) return new Intl.NumberFormat("es-EC", { maximumFractionDigits: 2 }).format(value) + "%";
+        return new Intl.NumberFormat("es-EC", { notation: Math.abs(value) >= 1000000 ? "compact" : "standard", maximumFractionDigits: 2 }).format(value);
+      };
+      const formatDate = value => {
+        if (!value) return "";
+        const parsed = new Date(value);
+        return Number.isNaN(parsed.getTime()) ? String(value) : new Intl.DateTimeFormat("es-EC", { day: "2-digit", month: "short", year: "numeric", timeZone: "UTC" }).format(parsed);
+      };
+      const orderedMetrics = values => {
+        const keys = Object.entries(values || {}).filter(([, value]) => number(value)).map(([key]) => key);
+        return [...new Set([...metricPriority.filter(key => keys.includes(key)), ...keys.sort()])];
+      };
+      const canonicalPlatform = value => {
+        const source = String(value || "").toLowerCase();
+        if (source.includes("instagram")) return "instagram";
+        if (source.includes("facebook")) return "facebook";
+        if (source.includes("tiktok")) return "tiktok";
+        return source;
+      };
+      const rowPlatform = row => canonicalPlatform(
+        row.source_platform || row.platform || (row.source_metrics || {}).publisher_platform || (row.source_metrics || {}).platform
+      );
+      const panel = (id, visible) => {
+        const section = document.getElementById(id);
+        const nav = document.querySelector('[data-target="' + id + '"]');
+        show(section, visible);
+        if (nav) show(nav, visible);
+      };
+
+      const company = meta.company_name || "Cuenta seleccionada";
+      const period = meta.period || {};
+      const periodText = [formatDate(period.start), formatDate(period.end)].filter(Boolean).join(" — ");
+      document.getElementById("company-name").textContent = company;
+      document.getElementById("report-period").textContent = periodText;
+      document.getElementById("generated-at").textContent = formatDate(meta.generated_at);
