+      document.getElementById("footer-period").textContent = periodText;
+      (Array.isArray(meta.platforms) ? meta.platforms : []).forEach(value => document.getElementById("hero-platforms").append(element("span", "chip", platformLabel(String(value)))));
+
+      const renderKpis = (containerId, values) => {
+        const container = document.getElementById(containerId);
+        const keys = orderedMetrics(values);
+        keys.forEach(key => {
