+        const coords = points.map(([, value], index) => x(index) + "," + y(value));
+        const area = document.createElementNS(ns, "polygon");
+        area.setAttribute("class", "chart-area");
+        area.setAttribute("points", left + "," + (height - bottom) + " " + coords.join(" ") + " " + (width - right) + "," + (height - bottom));
+        svg.append(area);
+        const line = document.createElementNS(ns, "polyline");
+        line.setAttribute("class", "chart-line"); line.setAttribute("points", coords.join(" ")); svg.append(line);
+        const tickEvery = Math.max(1, Math.ceil(points.length / 7));
+        points.forEach(([day, value], index) => {
+          const dot = document.createElementNS(ns, "circle");
+          dot.setAttribute("class", "chart-dot"); dot.setAttribute("cx", x(index)); dot.setAttribute("cy", y(value)); dot.setAttribute("r", 4);
+          const title = document.createElementNS(ns, "title");
+          title.textContent = formatDate(day) + ": " + format(metric, value); dot.append(title); svg.append(dot);
+          if (index % tickEvery === 0 || index === points.length - 1) {
+            const label = document.createElementNS(ns, "text");
+            label.setAttribute("class", "chart-label"); label.setAttribute("data-trend-tick", "true");
+            label.setAttribute("x", x(index)); label.setAttribute("y", height - 17); label.setAttribute("text-anchor", "end");
+            label.setAttribute("transform", "rotate(-28 " + x(index) + " " + (height - 17) + ")");
+            label.textContent = formatDate(day); svg.append(label);
+          }
+        });
+        document.getElementById(prefix + "-trend-label").textContent = metricLabel(metric);
+        const body = document.getElementById(prefix + "-trend-body");
+        points.forEach(([day, value]) => {
+          const row = element("tr"); row.append(element("td", "", formatDate(day))); row.append(element("td", "", format(metric, value))); body.append(row);
+        });
+        return true;
+      };
+
+      const generalNarratives = narratives.filter(item => typeof item === "string" || (item && !item.platform));
+      generalNarratives.map(item => typeof item === "string" ? item : item.text || item.summary || item.value).filter(Boolean).forEach(value => {
+        const node = element("p", "narrative", value); node.dataset.family = "narrative"; document.getElementById("summary-narratives").append(node);
+      });
+      const summaryKpis = renderKpis("summary-kpis", summary);
+      const hasSummaryTrend = renderTrend("summary", series);
+      show(document.getElementById("summary-trend"), hasSummaryTrend);
